def mark_existing_team_history_unknown(apps, schema_editor):
    # No delivery records existed for team emails. Do not invent successful sends.
    database = schema_editor.connection.alias
    team_model = apps.get_model("tab", "Team")
    setting = apps.get_model("tab", "TabSettings").objects.using(database).filter(
        key="tournament_name",
    ).first()
    tournament_name = "Tournament"
    if setting:
        configured_name = (
            setting.value_string if setting.value_string is not None else setting.value
        )
        if configured_name is not None:
            tournament_name = configured_name
    pending = []
    for team in team_model.objects.using(database).prefetch_related("debaters").iterator(
        chunk_size=500,
    ):
        debaters = list(team.debaters.all())
        team.code_email_history_unknown = True
        team.code_email_baseline = {
            "name": team.name,
            "team_code": team.team_code,
            "debaters": sorted(debater.name for debater in debaters),
            "recipients": sorted({
                debater.email.strip().lower() for debater in debaters
                if debater.email and debater.email.strip()
            }),
            "tournament_name": tournament_name,
        }
        pending.append(team)
        if len(pending) == 500:
            team_model.objects.using(database).bulk_update(
                pending, ["code_email_history_unknown", "code_email_baseline"],
            )
            pending = []
    if pending:
        team_model.objects.using(database).bulk_update(
            pending, ["code_email_history_unknown", "code_email_baseline"],
        )


